package app.dayflow;
import android.content.Context;import android.os.Build;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.net.HttpURLConnection;import java.nio.file.*;import java.security.MessageDigest;import java.util.*;import java.util.zip.*;
/** Optional native engine, pinned publisher signature + archive/library hashes. Never external code. */
public final class VoiceEngine {
 private static boolean loaded;
 private static AtomicFile manifest(Context c){return new AtomicFile(new File(c.getFilesDir(),"voice/engine.json"));}
 private static String abi()throws Exception{for(String value:Build.SUPPORTED_ABIS)if(value.equals("arm64-v8a")||value.equals("armeabi-v7a"))return value;throw new IOException("本地引擎暂支持ARM手机；此设备可使用系统或百炼语音");}
 private static JSONObject payload(Context c,JSONObject envelope)throws Exception{JSONObject p=Updates.signedPayload(c,envelope);int base=c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionCode;if(p.getInt("schema")!=1||!"android-voice-engine".equals(p.getString("platform"))||p.getInt("api")!=1||p.getLong("version_code")<=0||p.getInt("min_app_code")>base||p.getInt("max_app_code")<base)throw new IOException("语音引擎不兼容当前基础版本");return p;}
 private static String hash(File file)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] buffer=new byte[32768];int n;while((n=in.read(buffer))!=-1)digest.update(buffer,0,n);}StringBuilder out=new StringBuilder();for(byte value:digest.digest())out.append(String.format(Locale.ROOT,"%02x",value&255));return out.toString();}
 public static synchronized void load(Context c)throws Exception{if(loaded)return;if(!manifest(c).getBaseFile().exists())throw new IOException("请先下载本地语音识别引擎");JSONObject envelope;try(InputStream in=manifest(c).openRead()){envelope=new JSONObject(Network.read(in,65536));}JSONObject p=payload(c,envelope),info=p.getJSONObject("files").getJSONObject(abi());File lib=new File(c.getFilesDir(),"voice/engine-"+p.getLong("version_code")+".so");if(lib.length()!=info.getLong("library_size")||!hash(lib).equals(info.getString("library_sha256")))throw new IOException("语音引擎校验失败，请重新下载");if(!lib.setReadOnly())throw new IOException("无法保护本地语音引擎");System.load(lib.getAbsolutePath());loaded=true;}
 public static synchronized String download(Context c)throws Exception{
  JSONObject envelope=UpdateSources.json(c,"voice-engine.json"),p=payload(c,envelope),info=p.getJSONObject("files").getJSONObject(abi());long version=p.getLong("version_code"),size=info.getLong("size"),librarySize=info.getLong("library_size");if(version<UpdateSources.prefs(c).getLong("voice_engine_highwater",0))throw new IOException("拒绝语音引擎版本降级");if(size<=0||size>64L*1024*1024||librarySize<=0||librarySize>64L*1024*1024)throw new IOException("引擎大小无效");String name=abi().equals("arm64-v8a")?"voice-engine-arm64.zip":"voice-engine-armv7.zip";
  File dir=new File(c.getFilesDir(),"voice");dir.mkdirs();File archive=new File(dir,"engine.part"),temp=new File(dir,"engine-library.part"),target=new File(dir,"engine-"+version+".so");HttpURLConnection connection=UpdateSources.open(c,name);long total=0;
  try{try(InputStream in=connection.getInputStream();OutputStream out=new FileOutputStream(archive)){byte[] block=new byte[32768];int n;while((n=in.read(block))!=-1){if(Thread.currentThread().isInterrupted())throw new IOException("下载已取消");total+=n;if(total>size)throw new IOException("引擎包长度不符");out.write(block,0,n);}}finally{connection.disconnect();}if(total!=size||!hash(archive).equals(info.getString("sha256")))throw new IOException("引擎包校验失败");
   temp.delete();try(ZipInputStream zip=new ZipInputStream(new FileInputStream(archive));FileOutputStream out=new FileOutputStream(temp)){if(!temp.setReadOnly())throw new IOException("无法保护下载的引擎");ZipEntry entry=zip.getNextEntry();if(entry==null||!entry.getName().equals("libdayflow_asr.so"))throw new IOException("无效引擎资源");byte[] block=new byte[32768];int n;long bytes=0;while((n=zip.read(block))!=-1){bytes+=n;if(bytes>librarySize)throw new IOException("引擎展开长度不符");out.write(block,0,n);}if(bytes!=librarySize||zip.getNextEntry()!=null)throw new IOException("引擎包内容不符");}
   if(!hash(temp).equals(info.getString("library_sha256")))throw new IOException("引擎代码校验失败");Files.move(temp.toPath(),target.toPath(),StandardCopyOption.REPLACE_EXISTING);
   AtomicFile f=manifest(c);FileOutputStream out=null;try{out=f.startWrite();out.write(envelope.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw e;}UpdateSources.prefs(c).edit().putLong("voice_engine_highwater",version).commit();File[] files=dir.listFiles();if(files!=null)for(File old:files)if(old.getName().matches("engine-\\d+\\.so")&&!old.equals(target))old.delete();return loaded?"引擎已更新，重新启动日栖后使用新版":"本地引擎已就绪，无需安装";
  }finally{archive.delete();temp.delete();}
 }
}
